const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2023 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n:host {\n  --override-transparent: rgb(0 0 0 / 0%);\n\n  border-radius: 3px;\n  width: fit-content;\n  display: flex;\n  align-items: center;\n  background-color: var(--override-menu-background-color, var(--color-background));\n}\n\n:host([has-open-dialog]) {\n  background-color: var(--override-menu-active-background-color, var(--color-background-elevation-2));\n}\n\n#container {\n  list-style-type: none;\n  margin: 0;\n  padding: 0;\n  width: fit-content;\n  display: block;\n}\n\n#container:focus {\n  outline: none;\n}\n\n@keyframes slideIn {\n  from {\n    transform: var(--translate-dialog);\n    opacity: 0%;\n  }\n\n  to {\n    transform: none;\n    opacity: 100%;\n  }\n}\n\n/*# sourceURL=menu.css */\n");export default styles;